"""Recover exact main 2D ruins references, not new art. No source mutation."""
import hashlib,json,subprocess,sys
from pathlib import Path
out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=True)
ref='d608469af9457937d22c5e2d4369fcecb1358926'
locks=json.loads(r'''[{"path":"assets/images/environments/moss_ancient_altar_idle_v1.png","git_blob":"9e18809ecb712524b47c9b00ad3ec02734347d08","bytes":3273807},{"path":"data/maps/moss_forest_03_ancient_grove.json","git_blob":"99449f538e07dc31ecc3b6e1f6701709e2d8f7da","bytes":43396},{"path":"docs/art/chatgpt_moss_forest_map_brief.md","git_blob":"dafecdc6919aa40b79b6b0f22c4b8e6edcbc0e64","bytes":25529},{"path":"img/field/moss/art/anc_arch_broken_01.png","git_blob":"2ca644d3e1a5498cc789758ba3a10378ea0d2ee0","bytes":184963},{"path":"img/field/moss/art/anc_boundary_stone_01.png","git_blob":"acb515d3900b75e058646e9ed152f2daacbf009c","bytes":43700},{"path":"img/field/moss/art/anc_boundary_stone_02.png","git_blob":"ca53ad7097356067a2d76939574b1d3a14379d0a","bytes":37437},{"path":"img/field/moss/art/anc_rune_broken_01.png","git_blob":"00e8d9674c4d2fc699a5d10f87f07e6f0bec1fcf","bytes":58719},{"path":"img/field/moss/art/anc_rune_broken_02.png","git_blob":"20e232e0eecdaf593f265c95a13196b989214102","bytes":52863},{"path":"img/field/moss/art/anc_rune_decal_01.png","git_blob":"79998b3d79d7d96cd15285313ce5492ec4d4820d","bytes":102389},{"path":"img/field/moss/art/anc_rune_decal_02.png","git_blob":"906354cc79a89ad9a8047b84195accff7b6dc49f","bytes":103767},{"path":"img/field/moss/art/anc_rune_decal_03.png","git_blob":"734b962c1c6a23f4f528d95b3ae502078024a66b","bytes":109198},{"path":"img/field/moss/art/anc_rune_decal_04.png","git_blob":"7e8eeb5bbdc68f86e0f5de44123cfd52b90da716","bytes":110830},{"path":"img/field/moss/art/anc_shrine_frag_01.png","git_blob":"3d3b4c32dfd4643bf6d073793073d7858a19b2f5","bytes":103513},{"path":"img/field/moss/art/anc_shrine_frag_02.png","git_blob":"71f0b6033c1047d7c0e52ae1efbd0d1dec662247","bytes":61542},{"path":"img/field/moss/art/anc_standing_L_01.png","git_blob":"91f0f7341d091584aed6914b9057432dd7b56644","bytes":77601},{"path":"img/field/moss/art/anc_standing_L_02.png","git_blob":"1f17091940a39aaf4434215a0ed49faef317e104","bytes":71835},{"path":"img/field/moss/art/anc_standing_L_03.png","git_blob":"5829b13c7a5402af4f98cb7f751a1a7d809f0105","bytes":61820},{"path":"img/field/moss/art/anc_stone_marker_old_01.png","git_blob":"cd012a4b99ac858a79bd0a9ee797f3855e309610","bytes":49168},{"path":"img/field/moss/art/ruins_stone_01.png","git_blob":"0ba31d333115075fd4cdc1a123261bca55c693b5","bytes":46245},{"path":"img/field/moss/art/ruins_stone_02.png","git_blob":"b09c4d412d180a5b835b141e27ea61dddb9e565e","bytes":71862},{"path":"js/altar-art.js","git_blob":"396368e80d0e444b01b08b0b168a8056c187df9d","bytes":2222}]''')
for r in locks:
    b=subprocess.check_output(['git','show',ref+':'+r['path']])
    assert len(b)==r['bytes']
    assert hashlib.sha1(('blob '+str(len(b))+'\0').encode()+b).hexdigest()==r['git_blob']
    p=out/r['path'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b)
    r['sha256']=hashlib.sha256(b).hexdigest()
(out/'manifest.json').write_text(json.dumps({'main':ref,'files':locks},indent=2)+'\n')
print('verified',len(locks),'files')
